      "desc": "毕业照是室外自然光下拍的，而自然光是最诚实的灯光：底妆厚一点、眼影重一点都会被拍成粉感和脏感，所以这款妆的难度不在技术而在「克制的浓度」。它和日常妆最大的区别是腮红要刻意加重——照片会整体吃掉气色，唯一值得加量的就是腮红和唇色。新手最容易犯的错，一是按室内拍照的思路画了浓眼妆和浓修容，成片又凶又假；二是完全忽略学士帽，让帽檐在脸上压出阴影、还把额头和发际线的妆蹭掉。",
