  /* 通用新手技巧：任何妆容都用得上 */
  beginnerGeneral: [
    { t: '手抖怎么办', d: '小指或无名指轻撑在脸上当支点，手肘靠在桌面上，立刻就稳了。画眼线时尤其管用。' },
    { t: '光线很重要', d: '尽量在自然光或白光下化妆。暖黄光会让你下手变重，出门一看发现妆浓了一倍。' },
    { t: '镜子怎么用', d: '全脸用正常镜子，放大镜只用于细节（比如画眼线）。全程用放大镜会失去整体感。' },
    { t: '用手机检查', d: '画完用手机后置镜头拍一张。照片比镜子更容易暴露出色差、边界生硬、左右不对称。' },
    { t: '少量多次是万能解', d: '几乎所有化妆问题的根源都是「一次上太多」。宁可分三次叠，也不要一次涂厚。' },
    { t: '先完成一边再画另一边', d: '眉毛、眼妆都适用。同时画两边容易越改越歪。' },
    { t: '画坏了就卸掉重来', d: '不丢人，专业化妆师也常重画。半成品硬撑只会越描越糟。' }
  ],

